#!/bin/bash
# Print the three IP addresses that appear most often in access.log,
# most frequent first; ties broken by first appearance in the log.
awk '
{
    ip = $1
    count[ip]++
    if (!(ip in first_seen)) {
        first_seen[ip] = NR
    }
}
END {
    for (ip in count) {
        print count[ip] "\t" first_seen[ip] "\t" ip
    }
}
' access.log | sort -t $'\t' -k1,1nr -k2,2n | cut -f3 | head -3
